from pathlib import Path
import json,datetime,hashlib
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2]
def load(n):return json.loads((HERE/n).read_text())
rows=[]
def face(path,url,releaseUrl,releaseId,catalogue,country,note,review,provider):
 p=ROOT/path
 return {'localPath':path,'sourceUrl':url,'releaseUrl':releaseUrl,'releaseId':str(releaseId),'catalogue':catalogue,'country':country,'editionNote':note,'actualVsRepresentative':'representative','familyCopy':False,'visualReview':review,'provider':provider,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def add_caa(rid,title,note,review):
 xs=[x for x in load('downloaded-artwork.json')if x['recordId']==rid];a=xs[0]['release'];rec={'recordId':rid,'title':title,'action':'replace-identity-dependent-artwork','familyEditionEvidence':'capture-intake-left-2026-10-14.json','editionNote':note}
 for x in xs:
  rec[x['face']]=face(x['path'],x['url'],'https://musicbrainz.org/release/'+a['id'],a['id'],'; '.join(y.get('catalog-number','')for y in a.get('label-info',[])),a.get('country'),note,review[x['face']],'Cover Art Archive / MusicBrainz')
 rows.append(rec)
def add_disc(rid,title,metaFile,releaseId,downloadFile,frontIndex,backIndex,note,review,action='replace-identity-dependent-artwork'):
 d=next(x['data']for x in load(metaFile)if x['data']['id']==releaseId);ds=load(downloadFile);rec={'recordId':rid,'title':title,'action':action,'familyEditionEvidence':'capture-intake-left-2026-10-14.json','editionNote':note}
 for f,i in [('front',frontIndex),('back',backIndex)]:
  x=next(x for x in ds if (x.get('releaseId')or x.get('discogsId'))==releaseId and (x.get('imageIndex',x.get('index')))==i)
  rec[f]=face(x['path'],x['url'],d['uri'],releaseId,'; '.join(y['catno']for y in d['labels']),d['country'],note,review[f],'Discogs public release images')
 rows.append(rec)
add_disc('upper-left-06','Sing It Again Rod','discogs-candidates.json',438323,'downloaded-discogs-artwork.json',0,1,'1973 UK Mercury 6499 484 die-cut LP, representative of the photographed Canadian Mercury SRM1-680. Both faces are the outer glass-shaped sleeve, not the removable inner sleeve or live-photo foldout.',{'front':'Correct glass-shaped outer front with Rod portrait; no CD packaging. Square scan includes black surrounding the die cut.','back':'Correct red glass-shaped outer rear with track lists; matches the physical rear design in IMG3589. Inner portrait/white concert panels rejected.'})
add_caa('upper-left-36','Caravanserai','1972 US Columbia KC31610 vinyl gatefold (Santa Maria), representative archive copy. Family printing is Canadian; matrix/plant identity is not inferred.',{'front':'Blue desert/camel artwork with orange sun and Santana title, full LP outer front.','back':'Outer rear blue desert/camel artwork and star emblem, matching the outer jacket design. The text/credits gatefold interior is not substituted.'})
add_disc('upper-left-50','Brief Replies','brief-canadian-discogs.json',5732763,'downloaded-brief-canadian.json',0,2,'1970 Canadian Polydor 2425 022 LP gatefold, matching photographed label/catalogue/country at jacket level. Archive scans are a different worn copy, not the family copy; pressing/runouts unverified.',{'front':'Correct distorted group-photo outer front with yellow Ten Wheel Drive/Genya Ravan title.','back':'Correct black outer rear with title, small group photo, credits and distorted colour figure; 2425-022 on Polydor logo. The wide band/lyrics interior at image1 is rejected as a back.'})
add_disc('upper-left-56','Between the Buttons','discogs-candidates.json',2931906,'downloaded-discogs-artwork.json',0,1,'1967 US London MONO LL3499 LP, matching the photographed mono catalogue and US programme. Family Canadian printing/pressing details are not certified by this US archive copy. Replaces the old stereo PS499 representative art.',{'front':'LP group photo explicitly marked LONDON MONO LL3499; no stereo PS499 lettering.','back':'Full Charlie Watts cartoon outer rear and twelve-track US programme, including Let’s Spend the Night Together and Ruby Tuesday. UK LK4852 programme is not substituted.'},'replace-stereo-representative-with-mono-LP-art')
add_disc('lower-left-07','Magician’s Hat','bo-north-american-discogs.json',4301782,'downloaded-bo-north-american.json',0,1,'1973 Canadian Charisma FC6062 LP, matching photographed plain-title cover layout and Canadian catalogue. Archive jacket has wear; actual family pressing/runouts not established.',{'front':'Plain cream title on black top band with fantasy landscape, matching family layout; UK/German decorative-lettering variants rejected in favour of this edition.','back':'Piano-in-forest outer rear, FC6062 upper right, eleven-song programme and WEA Canada credit below. Not a label or interior.'})
rs=load('downloaded-museum-artwork.json');note='Museum of Canadian Music scans of a Jabula/Kerygma LP edition, not the photographed United Artists UA-LA126-F. Same front painting and purple bird outer-back design, different label/catalogue printing. Museum date1971 is not used to assert the family issue date.'
rec={'recordId':'lower-left-12','title':'The Ecstasy of Rita Joe','action':'replace-identity-dependent-artwork','editionNote':note,'familyEditionEvidence':'capture-intake-left-2026-10-14.json'}
for f in ['front','back']:
 x=next(x for x in rs if x['face']==f);rec[f]=face(x['path'],x['url'],x['sourceUrl'],'citizenfreak-280545','KRS1005 / JR34','Canada',note,{'front':'Flat LP painting/credits front, Jabula logo visible; family United Artists logo differs.','back':'Full purple bird/circular-credits outer rear; source explicitly names BACK. A small old catalogue/price sticker remains. Museum gatefold-inside scans rejected.'}[f],'Museum of Canadian Music')
rows.append(rec)
