add_caa('lower-left-50','Okie','1974 US Shelter SR2107 LP, matching the photographed catalogue/programme. Family Canadian manufacturing is distinct; representative US archive copy.',{'front':'Four-panel colour painting LP front with JJ Cale / Okie title, no CD banner.','back':'Correct portrait outer rear with twelve-song programme and Shelter imprint; no label or inner sleeve.'})
