add_disc('lower-left-57','Dire Straits','dire-canadian-discogs.json',30067528,'downloaded-dire-canadian.json',0,1,'1978 Canadian Mercury SRM-1-1197 LP, matching photographed catalogue/country/outer artwork. Lacquer and pressing-plant details are not established for the family copy.',{'front':'Original grey/cream-framed blurred portrait front with Dire Straits title; Canadian Mercury variant.','back':'Four band portraits, nine-track programme, Canadian credits and Mercury logo on complete outer rear; no inner lyrics or label.'})
proposal={'version':1,'status':'proposal-only','createdAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Clean external LP faces for ten newly identified/corrected albums plus mono Between the Buttons. Existing valid artwork on unchanged anchors is preserved. No served asset/canonical changes.','counts':{'records':len(rows),'fronts':len(rows),'outerBacks':len(rows),'familyPhotoFallbacks':0},'records':rows,'preserveExistingCleanArtFor':['upper-left-08','upper-left-19','upper-left-39','upper-left-52','upper-left-54','upper-left-55','upper-left-57','lower-left-46','lower-left-48','lower-left-49','lower-left-51','lower-left-52'],'rejectedFacePitfalls':['Rod Canadian1783030 images1/2 are labels;3 is removable inner front;4/5 are inner concert panels, not the outer rear.','Genesis1480145 image1 is the wide lyric gatefold; select image2 outer rear.','BriefReplies5732763 image1 is band/lyrics inner gatefold; select image2 outer rear.','Bo905882 image1 and Dire6398906 image1 are labels, not backs.','BriefReplies Japan MP2120 uses a materially different black-and-white rear; not selected.','BetweenButtons UK LK4852 has a different programme, not selected.']}
(HERE.parent/'capture-intake-artwork-left-2026-10-14.json').write_text(json.dumps(proposal,ensure_ascii=False,indent=2)+'\n');print('records',len(rows))
